theorem addVal_single_neg_mul_of_addVal_eq {x : HahnField k Γ} {γ : Γ}
    (hx : addVal k Γ x = (γ : WithTop Γ)) :
    addVal k Γ (toLex (HahnSeries.single (-γ) (1 : k)) * x) = 0

theorem coeff_eq_zero_of_mem_valuationSubring_of_neg {x : HahnField k Γ}
    (hx : x ∈ valuationSubring k Γ) {γ : Γ} (hγ : γ < 0) :
    (ofLex x).coeff γ = 0

theorem exists_pos_nsmul_eq [DivisibleBy Γ ℕ] {m : ℕ} {γ : Γ}
    (hm : 0 < m) (hγ : 0 < γ) :
    ∃ δ : Γ, 0 < δ ∧ m • δ = γ

theorem exists_root_of_scalePolynomial_root {F : (HahnField k Γ)[X]} {δ lam : Γ}
    (hroot : ∃ y : HahnField k Γ, (scalePolynomial k Γ F δ lam).IsRoot y) :
    ∃ x : HahnField k Γ, F.IsRoot x

theorem isRoot_of_scalePolynomial_isRoot {F : (HahnField k Γ)[X]} {δ lam : Γ}
    {y : HahnField k Γ} (hy : (scalePolynomial k Γ F δ lam).IsRoot y) :
    F.IsRoot (hahnMonomial k Γ δ * y)

theorem le_addVal_add_of_le_addVal {x y : HahnField k Γ} {γ : WithTop Γ}
    (hx : γ ≤ addVal k Γ x) (hy : γ ≤ addVal k Γ y) :
    γ ≤ addVal k Γ (x + y)

theorem leadingCoeff_eq_coeff_of_addVal_eq {x : HahnField k Γ} {γ : Γ}
    (hx : addVal k Γ x = (γ : WithTop Γ)) :
    (ofLex x).leadingCoeff = (ofLex x).coeff γ

theorem leadingCoeff_eq_coeff_zero_of_addVal_eq_zero {x : HahnField k Γ}
    (hx : addVal k Γ x = 0) :
    (ofLex x).leadingCoeff = (ofLex x).coeff 0

theorem lt_addVal_of_le_addVal_of_coeff_eq_zero {x : HahnField k Γ} {γ : Γ}
    (hle : (γ : WithTop Γ) ≤ addVal k Γ x) (hcoeff : (ofLex x).coeff γ = 0) :
    (γ : WithTop Γ) < addVal k Γ x

theorem nonneg_of_mem_valuationSubring_coeff_ne_zero {x : HahnField k Γ}
    (hx : x ∈ valuationSubring k Γ) {γ : Γ} (hγ : (ofLex x).coeff γ ≠ 0) :
    0 ≤ γ

theorem nsmul_lt_of_lt_div [DivisibleBy Γ ℕ] {m : ℕ} (hm : m ≠ 0) {δ a : Γ}
    (hδ : δ < DivisibleBy.div a m) :
    m • δ < a

theorem scaledValue_pos_of_dominating {n i : ℕ} (hi : i ≤ n) {γn vi δ : Γ}
    (hdom : (n - i) • δ < vi - γn) :
    0 < -(γn + n • δ) + vi + i • δ

theorem PositiveHahnRoot.isRoot {F : (HahnField k Γ)[X]}
    (h : PositiveHahnRoot k Γ F) :
    F.IsRoot (PositiveHahnRoot.some k Γ h)

theorem PositiveHahnRoot.of_dvd {F G : (HahnField k Γ)[X]}
    (hroot : PositiveHahnRoot k Γ G) (hdiv : G ∣ F) :
    PositiveHahnRoot k Γ F

theorem PositiveHahnRoot.of_mul_left {F G H : (HahnField k Γ)[X]}
    (hroot : PositiveHahnRoot k Γ G) (hF : F = G * H) :
    PositiveHahnRoot k Γ F

theorem PositiveHahnRoot.pos {F : (HahnField k Γ)[X]}
    (h : PositiveHahnRoot k Γ F) :
    (0 : WithTop Γ) < addVal k Γ (PositiveHahnRoot.some k Γ h)

theorem addVal_add_gt_of_forall_gt {x y : HahnField k Γ} {γ : Γ}
    (hx : (γ : WithTop Γ) < addVal k Γ x) (hy : (γ : WithTop Γ) < addVal k Γ y) :
    (γ : WithTop Γ) < addVal k Γ (x + y)

theorem addVal_sum_gt_of_forall_gt {ι : Type*} {s : Finset ι}
    {f : ι → HahnField k Γ} {γ : Γ}
    (hf : ∀ i ∈ s, (γ : WithTop Γ) < addVal k Γ (f i)) :
    (γ : WithTop Γ) < addVal k Γ (∑ i ∈ s, f i)

theorem addVal_sum_pos_of_forall_pos {ι : Type*} {s : Finset ι}
    {f : ι → HahnField k Γ}
    (hf : ∀ i ∈ s, (0 : WithTop Γ) < addVal k Γ (f i)) :
    (0 : WithTop Γ) < addVal k Γ (∑ i ∈ s, f i)
